#!/usr/bin/env node
'use strict';

/**
 * Generates the protocol-V2 vector families from the PRODUCTION implementation (docs/protocol/VECTORS-FORMAT.md):
 *
 *   docs/protocol/vectors/v2-canon.json     V2-CANON-nnn   JCS-P1 canonicalization (V2-FREEZE section 2)
 *   docs/protocol/vectors/v2-request.json   V2-REQ-nnn     V2 request binding       (V2-FREEZE section 3)
 *   docs/protocol/vectors/INDEX.json        case counts of every vector file (pinned by a test); receipt.json (V2-RECEIPT-nnn) is generated by gen-receipt-vectors.js,
 *                                           audit-v8.json (AUDIT-V8-nnn) and audit-proof.json (AUDIT-PROOF-nnn) by gen-audit-vectors.js
 *
 * The inputs live in v2-vector-cases.js (bytes only). The expected values are what src/validation/jcsP1.js and requestBindingV2.js produce; they
 * are then re-derived by two independent verifiers that import nothing from src/ (verify-v2-vectors.js, verify_v2_vectors.py). A disagreement is
 * a defect in the specification text, the implementation, or a verifier — never settled by editing a vector.
 *
 *   node scripts/protocol/gen-v2-vectors.js            write the files
 *   node scripts/protocol/gen-v2-vectors.js --check    regenerate in memory and compare with the committed files (exit 1 on any difference)
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { canon, req } = require('./v2-vector-cases');
const { parseJcsP1, JcsError } = require('../../src/validation/jcsP1');
const { computeRequestHashV2, buildDocument, BindingError } = require('../../src/validation/requestBindingV2');
const { canonicalJcsP1 } = require('../../src/validation/jcsP1');

const DIR = path.join(__dirname, '..', '..', 'docs', 'protocol', 'vectors');
const SPEC_VERSION = 'v2-freeze-1';
const GENERATED_BY = 'scripts/protocol/gen-v2-vectors.js';
const TEXT_LIMIT = 160;
const HEX_LIMIT = 4096;

const BYTES_SCHEMA = { oneOf: [
  { type: 'string', pattern: '^([0-9a-f]{2})*$', description: 'lower-case hex' },
  { type: 'object', required: ['repeat'], additionalProperties: false, properties: { repeat: { type: 'object', required: ['prefix', 'unit', 'count', 'suffix'], properties: { prefix: { type: 'string' }, unit: { type: 'string' }, count: { type: 'integer', minimum: 0 }, suffix: { type: 'string' } } } }, description: 'prefix + unit x count + suffix (UTF-8 text)' },
] };

function expand(b) {
  if (typeof b === 'string') return Buffer.from(b, 'hex');
  const { prefix, unit, count, suffix } = b.repeat;
  return Buffer.from(prefix + unit.repeat(count) + suffix, 'utf8');
}
const latin1 = (b) => expand(b).toString('latin1');
const pad = (n) => String(n).padStart(3, '0');

function canonFile() {
  const cases = canon.map((c, i) => {
    const id = `V2-CANON-${pad(i + 1)}`;
    const base = { id, description: c.desc, input: { bytes: c.bytes } };
    try {
      const { canonical } = parseJcsP1(expand(c.bytes));
      const bytes = Buffer.from(canonical, 'utf8');
      // a large canonical output (the size-limit cases) is pinned by its length and SHA-256 instead of inlining a megabyte of hex
      const expected = bytes.length <= HEX_LIMIT ? { outcome: 'ok', value: bytes.toString('hex') } : { outcome: 'ok', length: bytes.length, sha256: crypto.createHash('sha256').update(bytes).digest('hex') };
      if (bytes.length <= TEXT_LIMIT) expected.text = canonical;
      return { ...base, expected };
    } catch (e) {
      if (!(e instanceof JcsError)) throw e;
      return { ...base, expectedError: { code: e.code } };
    }
  });
  return {
    format: 'qodiqa-vectors/1', family: 'v2-canon', generatedBy: GENERATED_BY, specVersion: SPEC_VERSION, mode: 'compute', nowMs: 0,
    inputSchema: { type: 'object', required: ['bytes'], properties: { bytes: BYTES_SCHEMA }, description: 'UTF-8 JSON text (or any bytes) to parse under JCS-P1; expected.value is the canonical text as hex (for a canonical output above 4096 bytes: expected.length and expected.sha256 of the canonical bytes instead), or expectedError.code the FIRST rule broken (V2-FREEZE 2.7)' },
    keys: [], cases,
  };
}

function requestFile() {
  const cases = req.map((c, i) => {
    const id = `V2-REQ-${pad(i + 1)}`;
    const input = { method: c.method, target: c.target, headers: c.headers, bind: c.bind, body: c.body };
    const base = { id, description: c.desc, input };
    // Node hands the gateway the raw header list and the request-target as latin1 strings of the received bytes.
    const rawHeaders = [];
    for (const [n, v] of c.headers) rawHeaders.push(latin1(n), latin1(v));
    const request = { method: latin1(c.method), target: latin1(c.target), rawHeaders, body: c.body === null ? Buffer.alloc(0) : expand(c.body) };
    try {
      const value = computeRequestHashV2(request, c.bind);
      const expected = { outcome: 'ok', value };
      const doc = canonicalJcsP1(buildDocument(request, c.bind));
      if (Buffer.byteLength(doc, 'utf8') <= TEXT_LIMIT * 2) expected.document = doc;
      // the hash is SHA-256("QODIQA::REQUEST::V2" || document): the document text lets a verifier see which component differs
      return { ...base, expected };
    } catch (e) {
      if (!(e instanceof BindingError)) throw e;
      return { ...base, expectedError: { code: e.code, ...(e.jcsCode ? { detail: e.jcsCode } : {}) } };
    }
  });
  return {
    format: 'qodiqa-vectors/1', family: 'v2-request', generatedBy: GENERATED_BY, specVersion: SPEC_VERSION, mode: 'compute', nowMs: 0,
    inputSchema: {
      type: 'object', required: ['method', 'target', 'headers', 'bind', 'body'],
      properties: {
        method: BYTES_SCHEMA, target: { ...BYTES_SCHEMA, description: 'the raw request-target bytes' },
        headers: { type: 'array', items: { type: 'array', minItems: 2, maxItems: 2, items: BYTES_SCHEMA }, description: 'the received field lines in order: [name bytes, value bytes]' },
        bind: { type: 'array', items: { type: 'string' }, description: 'qodiqa.bind.headers of the artifact' },
        body: { oneOf: [{ type: 'null' }, BYTES_SCHEMA], description: 'null = no body at all; "" = zero bytes' },
      },
      description: 'expected.value is the requestHash(V2) (hex); expectedError.code is REQUEST_MISMATCH, with detail = the JCS-P1 code when the refusal is a canonicalization failure of a string or of the document',
    },
    keys: [], cases,
  };
}

function indexFile() {
  const files = {};
  const v1 = JSON.parse(fs.readFileSync(path.join(DIR, 'qodiqa-protocol-vectors.json'), 'utf8'));
  files['qodiqa-protocol-vectors.json'] = {
    family: 'v1', cases: {
      'canonicalization.valid': v1.canonicalization.valid.length, 'canonicalization.errors': v1.canonicalization.errors.length, 'domainTags.tags': v1.domainTags.tags.length,
      artifacts: v1.artifacts.length, 'verification.cases': v1.verification.cases.length, 'requestBinding.hashes': v1.requestBinding.hashes.length,
      'requestBinding.binding': v1.requestBinding.binding.length, 'policyHash.cases': v1.policyHash.cases.length,
    },
  };
  for (const [file, f] of [['v2-canon.json', FILES['v2-canon.json']], ['v2-request.json', FILES['v2-request.json']]]) {
    files[file] = { family: f.family, cases: f.cases.length, accepted: f.cases.filter((c) => c.expected).length, refused: f.cases.filter((c) => c.expectedError).length, sha256: crypto.createHash('sha256').update(render(f)).digest('hex') };
  }
  // receipt.json and the audit families are written by gen-receipt-vectors.js / gen-audit-vectors.js (run first): their case counts and digests are pinned here too
  for (const name of ['receipt.json', 'audit-v8.json', 'audit-proof.json', 'audit-anchor.json']) {
    const p = path.join(DIR, name);
    if (!fs.existsSync(p)) continue;
    const text = fs.readFileSync(p, 'utf8');
    const r = JSON.parse(text);
    const accepted = r.family === 'audit-proof' ? r.cases.filter((c) => c.expected.verdict !== 'INVALID').length : r.cases.filter((c) => c.expected).length;
    files[name] = { family: r.family, cases: r.cases.length, accepted, refused: r.cases.length - accepted, sha256: crypto.createHash('sha256').update(text).digest('hex') };
  }
  return { format: 'qodiqa-vectors-index/1', generatedBy: GENERATED_BY, specVersion: SPEC_VERSION, files };
}

const render = (o) => `${JSON.stringify(o, null, 1)}\n`;
const FILES = { 'v2-canon.json': canonFile(), 'v2-request.json': requestFile() };
FILES['INDEX.json'] = indexFile();

if (process.argv.includes('--check')) {
  const drift = [];
  for (const [name, obj] of Object.entries(FILES)) {
    const p = path.join(DIR, name);
    const committed = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null;
    if (committed !== render(obj)) drift.push(name);
  }
  process.stdout.write(`${JSON.stringify({ ok: drift.length === 0, drift })}\n`);
  if (drift.length) { process.stderr.write('[protocol-v2-vectors] DRIFT: the implementation no longer produces the committed vectors. Run `npm run protocol:vectors`, review the diff.\n'); process.exit(1); }
} else {
  for (const [name, obj] of Object.entries(FILES)) fs.writeFileSync(path.join(DIR, name), render(obj));
  process.stdout.write(`${JSON.stringify({ wrote: Object.keys(FILES), cases: { canon: FILES['v2-canon.json'].cases.length, request: FILES['v2-request.json'].cases.length } })}\n`);
}
module.exports = { FILES };
